def main(argv):
    # 首项为已知子命令时不丢弃（程序化调用），否则仅丢脚本名
    if argv[:1] and argv[0] in SUBCOMMANDS:
        args = list(argv)
    else:
        args = argv[1:]
    if args[:1] == ["record"]:
        # record CONFIG EVENTS LOG [MAX_EVENTS MAX_LOG_BYTES
        #   [MAX_CONFIG_BYTES MAX_EVENTS_BYTES [MAX_OUTPUT_BYTES
        #   [MAX_RECORD_WORK]]]]
        if len(args) not in (4, 6, 8, 9, 10):
            _fail("usage")
            return 2
        limits = _parse_limits(
            args[4:],
            (0, 2, 4, 5, 6),
            (
                DEFAULT_MAX_EVENTS,
                DEFAULT_MAX_LOG_BYTES,
                DEFAULT_MAX_CONFIG_BYTES,
                DEFAULT_MAX_EVENTS_BYTES,
                DEFAULT_MAX_OUTPUT_BYTES,
                DEFAULT_MAX_RECORD_WORK,
            ),
        )
        if limits is None:
            _fail("usage")
            return 2
        return _cmd_record(args[1], args[2], args[3], *limits)
    if args[:1] == ["replay"]:
        # replay LOG [MAX_EVENTS MAX_LOG_BYTES [MAX_OUTPUT_BYTES
        #   [MAX_REPLAY_WORK]]]
        # 或带外部承诺形式：
        # replay LOG --expect-sha256 EXPECTED [MAX_EVENTS MAX_LOG_BYTES
        #   [MAX_OUTPUT_BYTES [MAX_REPLAY_WORK]]]
        # EXPECTED 须为调用方从成功 record 产物顶层 sha256 独立保存的
        # 64 位小写十六进制，不得取自待重放 LOG；选项、数量或格式非法
        # 按 usage 退出 2。
        expected = None
        if len(args) >= 3 and args[2] == "--expect-sha256":
            # flag 后必须紧跟 EXPECTED，其后仅可跟 0、2、3、4 个上限
            if len(args) not in (4, 6, 7, 8):
                _fail("usage")
                return 2
            expected = args[3]
            if _HEX64_RE.fullmatch(expected) is None:
                _fail("usage")
                return 2
            limit_tokens = args[4:]
        else:
            # 旧形式逐字节保留：上限数量仅 0、2、3、4 个
            if len(args) not in (2, 4, 5, 6):
                _fail("usage")
                return 2
            limit_tokens = args[2:]
        limits = _parse_limits(
            limit_tokens,
            (0, 2, 3, 4),
            (
                DEFAULT_MAX_EVENTS,
                DEFAULT_MAX_LOG_BYTES,
                DEFAULT_MAX_OUTPUT_BYTES,
                DEFAULT_MAX_REPLAY_WORK,
            ),
        )
        if limits is None:
            _fail("usage")
            return 2
        return _cmd_replay(args[1], *limits, expected_sha256=expected)
    if args[:1] == ["log-filter"]:
        # log-filter LOG START END APPLIED [MAX_LOG_BYTES MAX_OUTPUT_BYTES]：
        # 两上限成对可选（0 或 2 个），均须匹配 [1-9][0-9]*，默认 16 MiB
        if len(args) not in (5, 7):
            _fail("usage")
            return 2
        limits = _parse_limits(
            args[5:],
            (0, 2),
            (DEFAULT_MAX_LOG_BYTES, DEFAULT_MAX_OUTPUT_BYTES),
        )
        if limits is None:
            _fail("usage")
            return 2
        return _cmd_log_filter(args[1], args[2], args[3], args[4], *limits)
    if args[:1] == ["log-summary"]:
        # log-summary LOG [MAX_LOG_BYTES MAX_OUTPUT_BYTES]：
        # 两上限成对可选（0 或 2 个），均须匹配 [1-9][0-9]*，默认 16 MiB；
        # 参数个数、格式与边界完全沿用 log-filter
        if len(args) not in (2, 4):
            _fail("usage")
            return 2
        limits = _parse_limits(
            args[2:],
            (0, 2),
            (DEFAULT_MAX_LOG_BYTES, DEFAULT_MAX_OUTPUT_BYTES),
        )
        if limits is None:
            _fail("usage")
            return 2
        return _cmd_log_summary(args[1], *limits)
    if args[:1] == ["log-counters"]:
        # log-counters LOG [MAX_LOG_BYTES MAX_OUTPUT_BYTES MAX_STATS_WORK]：
        # 三上限可省略或全给（0 或 3 个），前两项沿用 log-summary，
        # 末项默认 10000000；均须匹配 [1-9][0-9]*
        if len(args) not in (2, 5):
            _fail("usage")
            return 2
        limits = _parse_limits(
            args[2:],
            (0, 3),
            (
                DEFAULT_MAX_LOG_BYTES,
                DEFAULT_MAX_OUTPUT_BYTES,
                DEFAULT_MAX_STATS_WORK,
            ),
        )
        if limits is None:
            _fail("usage")
            return 2
        return _cmd_log_counters(args[1], *limits)
    if args[:1] == ["log-page"]:
        # log-page LOG CURSOR COUNT [MAX_LOG_BYTES MAX_OUTPUT_BYTES]：
        # 两上限成对可选（0 或 2 个），均须匹配 [1-9][0-9]*，默认 16 MiB；
        # 参数格式、分块读取与字节边界完全沿用 log-filter
        if len(args) not in (4, 6):
            _fail("usage")
            return 2
        limits = _parse_limits(
            args[4:],
            (0, 2),
            (DEFAULT_MAX_LOG_BYTES, DEFAULT_MAX_OUTPUT_BYTES),
        )
        if limits is None:
            _fail("usage")
            return 2
        return _cmd_log_page(args[1], args[2], args[3], *limits)
    if args[:1] == ["log-query"]:
        # log-query LOG START END KIND APPLIED CURSOR COUNT
        #   [MAX_LOG_BYTES MAX_OUTPUT_BYTES]：
        # 两上限成对可选（0 或 2 个），均须匹配 [1-9][0-9]*，默认 16 MiB；
        # START/END/APPLIED 沿用 log-filter，KIND 取 * 或七类已知事件，
        # CURSOR/COUNT 与参数格式、分块读取、字节边界沿用 log-page
        if len(args) not in (8, 10):
            _fail("usage")
            return 2
        limits = _parse_limits(
            args[8:],
            (0, 2),
            (DEFAULT_MAX_LOG_BYTES, DEFAULT_MAX_OUTPUT_BYTES),
        )
        if limits is None:
            _fail("usage")
            return 2
        return _cmd_log_query(
            args[1], args[2], args[3], args[4], args[5], args[6], args[7],
            *limits
        )
    if args[:1] == ["log-fdb"]:
        # log-fdb LOG CURSOR [MAX_WORK]：CURSOR 沿用 log-page（* 或
        # <sha256>:<offset>），MAX_WORK 为不限长正十进制，默认 10000000；
        # 个数或格式非法按 usage 退出 2（在打开文件前判定）。输入/输出
        # 各限 16777216 字节（固定默认值）
        if len(args) not in (3, 4):
            _fail("usage")
            return 2
        if _PAGE_CURSOR_RE.fullmatch(args[2]) is None:
            _fail("usage")
            return 2
        if len(args) == 4 and _LIMIT_RE.fullmatch(args[3]) is None:
            _fail("usage")
            return 2
        max_work = (
            _limit_value(args[3]) if len(args) == 4
            else DEFAULT_MAX_FDB_WORK
        )
        return _cmd_log_fdb(args[1], args[2], max_work)
    if args[:1] == ["log-security"]:
        # log-security LOG CURSOR [MAX_WORK]：参数、资源、CURSOR 与错误
        # 顺序完全沿用 log-fdb；MAX_WORK 为不限长正十进制，默认
        # 10000000（security-check 工作量公式）
        if len(args) not in (3, 4):
            _fail("usage")
            return 2
        if _PAGE_CURSOR_RE.fullmatch(args[2]) is None:
            _fail("usage")
            return 2
        if len(args) == 4 and _LIMIT_RE.fullmatch(args[3]) is None:
            _fail("usage")
            return 2
        max_work = (
            _limit_value(args[3]) if len(args) == 4
            else DEFAULT_MAX_SECURITY_WORK
        )
        return _cmd_log_security(args[1], args[2], max_work)
    if args[:1] == ["log-qos"]:
        # log-qos LOG CURSOR [MAX_WORK]：参数、资源、CURSOR 与错误顺序
        # 完全沿用 log-security；MAX_WORK 为不限长正十进制，默认
        # 10000000（qos-check 工作量公式，qos-decode 日志解码后同口径）
        if len(args) not in (3, 4):
            _fail("usage")

    if not isinstance(config, dict) or frozenset(config) != LAG_CONFIG_KEYS:
        raise InvalidInput("bad config")
    bridges, links, delay, bridge, ports, age, storm = (
        validate_forward_stp_storm_config(
            {
                "bridges": config["bridges"],
                "links": config["links"],
                "delay": config["delay"],
                "bridge": config["bridge"],
                "ports": config["ports"],
                "age": config["age"],
                "storm": config["storm"],
            }
        )
    )
    lags = config["lags"]
    if not isinstance(lags, list) or not lags:
        raise InvalidInput("bad lags")
    by_name = {port["name"]: port for port in ports}
    names = []
    used = set()
    parsed = []
    for lag in lags:
        if not isinstance(lag, dict) or frozenset(lag) != LAG_KEYS:
            raise InvalidInput("bad lag")
        name = lag["name"]
        members = lag["members"]
        hash_fields = lag["hash"]
        if not isinstance(name, str) or not name or name in by_name:
            raise InvalidInput("bad lag name")
        if (
            not isinstance(members, list)
            or len(members) < 2
            or not all(isinstance(m, str) and m in by_name for m in members)
            or len(set(members)) != len(members)
        ):
            raise InvalidInput("bad lag members")
        if used.intersection(members):
            raise InvalidInput("lag members must be globally distinct")
        used.update(members)
        first = by_name[members[0]]
        for member in members[1:]:
            port = by_name[member]
            if (
                port["mode"] != first["mode"]
                or port["pvid"] != first["pvid"]
                or port["allowed"] != first["allowed"]
                or port["untagged"] != first["untagged"]
            ):
                raise InvalidInput("lag members must share vlan config")
        if (
            not isinstance(hash_fields, list)
            or not hash_fields
            or len(set(hash_fields)) != len(hash_fields)
            or any(field not in LAG_HASH_FIELDS for field in hash_fields)
            or [f for f in LAG_HASH_FIELDS if f in hash_fields] != hash_fields
        ):
            raise InvalidInput("bad lag hash")
        names.append(name)
        parsed.append(
            {"name": name, "members": list(members), "hash": list(hash_fields)}
        )
    if len(set(names)) != len(names):
        raise InvalidInput("lag names must be distinct")
    return bridges, links, delay, bridge, ports, age, storm, parsed


def validate_mirror_config(config):
    if not isinstance(config, dict) or frozenset(config) != MIRROR_CONFIG_KEYS:
        raise InvalidInput("bad config")
    bridges, links, delay, bridge, ports, age, storm, lags = validate_lag_config(
        {
            "bridges": config["bridges"],
            "links": config["links"],
            "delay": config["delay"],
            "bridge": config["bridge"],
            "ports": config["ports"],
            "age": config["age"],
            "storm": config["storm"],
            "lags": config["lags"],
        }
    )
    mirror = config["mirror"]
    if not isinstance(mirror, dict) or frozenset(mirror) != MIRROR_KEYS:
        raise InvalidInput("bad mirror")
    sources = mirror["sources"]
    target = mirror["target"]
    direction = mirror["direction"]
    by_name = {port["name"]: port for port in ports}
    member_set = {member for lag in lags for member in lag["members"]}
    if (
        not isinstance(sources, list)
        or not sources
        or not all(isinstance(name, str) and name in by_name for name in sources)
        or len(set(sources)) != len(sources)
    ):
        raise InvalidInput("bad mirror sources")
    if not isinstance(target, str) or target not in by_name:
        raise InvalidInput("bad mirror target")
    if target in sources or target in member_set:
        raise InvalidInput("bad mirror target")
    if direction not in MIRROR_DIRECTIONS:
        raise InvalidInput("bad mirror direction")
    parsed = {
        "sources": list(sources),
        "target": target,
        "direction": direction,
    }
    return bridges, links, delay, bridge, ports, age, storm, lags, parsed


def validate_acl_config(config):
    if not isinstance(config, dict) or frozenset(config) != ACL_CONFIG_KEYS:
        raise InvalidInput("bad config")
    (
        bridges,
        links,
        delay,
        bridge,
        ports,
        age,
        storm,
        lags,
        mirror,
    ) = validate_mirror_config(
        {
            "bridges": config["bridges"],
            "links": config["links"],
            "delay": config["delay"],
            "bridge": config["bridge"],
            "ports": config["ports"],
            "age": config["age"],
            "storm": config["storm"],
            "lags": config["lags"],
            "mirror": config["mirror"],
        }
    )
    acl = config["acl"]
    if not isinstance(acl, list) or not acl:
        raise InvalidInput("bad acl")
    parsed = []
    for rule in acl:
        if not isinstance(rule, dict) or frozenset(rule) != ACL_RULE_KEYS:
            raise InvalidInput("bad acl rule")
        src = rule["src"]
        dst = rule["dst"]
        vlan = rule["vlan"]
        ethertype = rule["ethertype"]
        priority = rule["priority"]
        action = rule["action"]
        to_vlan = rule["to_vlan"]
        if src is not None and not valid_mac(src):
            raise InvalidInput("bad acl src")
        if dst is not None and not valid_dst_mac(dst):
            raise InvalidInput("bad acl dst")
        if vlan is not None and not _valid_vlan_id(vlan):
            raise InvalidInput("bad acl vlan")
        if ethertype is not None and not (
            _is_int(ethertype) and 0 <= ethertype <= 65535
        ):
            raise InvalidInput("bad acl ethertype")
        if priority is not None and not (
            _is_int(priority) and 0 <= priority <= 7
        ):
            raise InvalidInput("bad acl priority")
        if action not in ACL_ACTIONS:
            raise InvalidInput("bad acl action")
        if action == "remark":
            if not _valid_vlan_id(to_vlan):
                raise InvalidInput("bad acl to_vlan")
        elif to_vlan is not None:
            raise InvalidInput("bad acl to_vlan")
        parsed.append(
            {
                "src": src,
                "dst": dst,
                "vlan": vlan,
                "ethertype": ethertype,
                "priority": priority,
                "action": action,
                "to_vlan": to_vlan,
            }
        )
    return bridges, links, delay, bridge, ports, age, storm, lags, mirror, parsed


